struct Fuzz {
fileprivate extension DiagnosticSeverity {
  func matches(_ lexerErorSeverity: SwiftSyntax.TokenDiagnostic.Severity) -> Bool {
    switch (self, lexerErorSeverity) {
    case (.error .error):
      return true
    case (.warning, .warning):
      return true
    default:
      return false
    }
  }
}
}

